import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor triplet_margin_loss_forward(torch::Tensor anchor,
                                          torch::Tensor positive,
                                          torch::Tensor negative,
                                          double margin,
                                          double eps);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
#include <math.h>

using namespace cute;

template <typename T>
__global__ void triplet_margin_loss_kernel(
    const T* __restrict__ anchor,
    const T* __restrict__ positive,
    const T* __restrict__ negative,
    float* __restrict__ output,   // single accumulator (sum of losses)
    int batch_size,
    int dim,
    float margin,
    float eps)
{
    int row = blockIdx.x;
    if (row >= batch_size) return;

    const T* a_ptr = anchor   + (size_t)row * dim;
    const T* p_ptr = positive + (size_t)row * dim;
    const T* n_ptr = negative + (size_t)row * dim;

    // CuTe tensors over the row (1D, contiguous)
    auto mA = make_tensor(make_gmem_ptr(a_ptr), make_shape(dim), make_stride(Int<1>{}));
    auto mP = make_tensor(make_gmem_ptr(p_ptr), make_shape(dim), make_stride(Int<1>{}));
    auto mN = make_tensor(make_gmem_ptr(n_ptr), make_shape(dim), make_stride(Int<1>{}));

    int tid = threadIdx.x;
    int nthreads = blockDim.x;

    float sum_pos = 0.0f;
    float sum_neg = 0.0f;

    for (int i = tid; i < dim; i += nthreads) {
        float av = static_cast<float>(mA(i));
        float pv = static_cast<float>(mP(i));
        float nv = static_cast<float>(mN(i));

        float dp = av - pv + eps;
        float dn = av - nv + eps;

        sum_pos += dp * dp;
        sum_neg += dn * dn;
    }

    // Warp-level reduction
    unsigned mask = 0xffffffffu;
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
        sum_pos += __shfl_down_sync(mask, sum_pos, offset);
        sum_neg += __shfl_down_sync(mask, sum_neg, offset);
    }

    __shared__ float shared_pos[32];
    __shared__ float shared_neg[32];

    int lane_id = tid & 31;
    int warp_id = tid >> 5;

    if (lane_id == 0) {
        shared_pos[warp_id] = sum_pos;
        shared_neg[warp_id] = sum_neg;
    }
    __syncthreads();

    int num_warps = (nthreads + 31) >> 5;

    if (tid == 0) {
        float total_pos = 0.0f;
        float total_neg = 0.0f;
        for (int w = 0; w < num_warps; ++w) {
            total_pos += shared_pos[w];
            total_neg += shared_neg[w];
        }

        float d_pos = sqrtf(total_pos);
        float d_neg = sqrtf(total_neg);

        float loss = d_pos - d_neg + margin;
        loss = loss > 0.0f ? loss : 0.0f;

        atomicAdd(output, loss);
    }
}

__global__ void divide_scalar_kernel(float* data, int n) {
    if (blockIdx.x == 0 && threadIdx.x == 0) {
        data[0] = data[0] / static_cast<float>(n);
    }
}

torch::Tensor triplet_margin_loss_forward(torch::Tensor anchor,
                                          torch::Tensor positive,
                                          torch::Tensor negative,
                                          double margin,
                                          double eps) {
    TORCH_CHECK(anchor.is_cuda() && positive.is_cuda() && negative.is_cuda(),
                "All inputs must be CUDA tensors");
    TORCH_CHECK(anchor.dim() == 2 && positive.dim() == 2 && negative.dim() == 2,
                "Inputs must be 2D [batch, dim]");
    TORCH_CHECK(anchor.sizes() == positive.sizes() && anchor.sizes() == negative.sizes(),
                "Inputs must have the same shape");
    TORCH_CHECK(anchor.scalar_type() == at::kFloat &&
                positive.scalar_type() == at::kFloat &&
                negative.scalar_type() == at::kFloat,
                "Only float32 tensors supported");

    auto a_c = anchor.contiguous();
    auto p_c = positive.contiguous();
    auto n_c = negative.contiguous();

    int batch_size = (int)a_c.size(0);
    int dim = (int)a_c.size(1);

    auto out = torch::zeros({}, a_c.options());

    const int threads = 256;
    dim3 block(threads);
    dim3 grid(batch_size);

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    triplet_margin_loss_kernel<float><<<grid, block, 0, stream>>>(
        a_c.data_ptr<float>(),
        p_c.data_ptr<float>(),
        n_c.data_ptr<float>(),
        out.data_ptr<float>(),
        batch_size,
        dim,
        static_cast<float>(margin),
        static_cast<float>(eps)
    );

    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "triplet_margin_loss_kernel launch failed: ", cudaGetErrorString(err));

    divide_scalar_kernel<<<1, 1, 0, stream>>>(out.data_ptr<float>(), batch_size);

    err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "divide_scalar_kernel launch failed: ", cudaGetErrorString(err));

    return out;
}
"""

triplet_ext = load_inline(
    name="cute_triplet_margin_loss_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["triplet_margin_loss_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    A model that computes Triplet Margin Loss for metric learning tasks,
    using a fused custom CUDA/CuTe kernel.

    Parameters:
        margin (float): The margin between the positive and negative samples.
    """
    def __init__(self, margin=1.0):
        super(ModelNew, self).__init__()
        self.margin = float(margin)
        self.eps = 1e-6
        self._ext = triplet_ext

    def forward(self, anchor, positive, negative):
        return self._ext.triplet_margin_loss_forward(
            anchor, positive, negative, self.margin, self.eps
        )

