        self.eps = 1e-6

    def forward(self, anchor, positive, negative):
        assert anchor.is_cuda and positive.is_cuda and negative.is_cuda, \
            "All inputs must be CUDA tensors"
        assert anchor.dim() == 2 and positive.dim() == 2 and negative.dim() == 2, \
            "Inputs must be 2D [batch, dim]"
        assert anchor.shape == positive.shape == negative.shape, \
            "Inputs must have the same shape"
        assert anchor.dtype == torch.float32 and positive.dtype == torch.float32 \
            and negative.dtype == torch.float32, "Only float32 tensors supported"

        a_c = anchor.contiguous()
        p_c = positive.contiguous()
        n_c = negative.contiguous()

        batch_size = int(a_c.size(0))
        dim = int(a_c.size(1))

        out = torch.zeros((), device=a_c.device, dtype=torch.float32)

        module = _get_module()
        fn_main = module.function("triplet_margin_loss_kernel")
        fn_div = module.function("divide_scalar_kernel")

        stream = torch.cuda.current_stream().cuda_stream

        threads = 256
        fn_main.launch(
            grid=(batch_size, 1, 1),
            block=(threads, 1, 1),
            shared_mem=0,
            stream=stream,
            args=[
                u64(a_c.data_ptr()),
                u64(p_c.data_ptr()),
                u64(n_c.data_ptr()),
                u64(out.data_ptr()),
                i32(batch_size),
                i32(dim),
                f32(self.margin),
                f32(self.eps),
            ],
        )

        fn_div.launch(
            grid=(1, 1, 1),
            block=(1, 1, 1),
            shared_mem=0,
            stream=stream,
            args=[
                u64(out.data_ptr()),
                i32(batch_size),
            ],
        )

        return out
